<script setup>
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '../../stores/authStore'
import { isStepUpCancelled, useStepUpAuth } from '../../composables/useStepUpAuth'
import { gradingError, gradingService } from './gradingService'
import ProfessorGradeMessages from './ProfessorGradeMessages.vue'
import StudentGradesView from './StudentGradesView.vue'
import './grading.css'

const auth=useAuthStore(), professor=computed(()=>auth.currentRole==='Professor'), student=computed(()=>auth.currentRole==='Student')
const { runWithStepUp }=useStepUpAuth()
const loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),classes=ref([]),periods=ref([]),options=ref({academic_years:[],semesters:[]}),workspace=ref(null),search=ref(''),activePeriod=ref('midterm'),modal=ref('')
const staffTab=ref('periods'),reviewData=ref({summary:{pending_review:0,approved:0,published:0},sheets:{data:[]}}),releaseData=ref({approved_sheets:[],schedules:{data:[]}}),reviewSheet=ref(null),readiness=ref(null),returnReason=ref('')
const professorTab=ref('classes')
const reviewFilters=ref({search:'',academic_year_id:'',semester_id:'',course_id:'',year_level:'',section_id:'',subject_id:'',professor_id:'',status:''})
const releaseForm=ref({academic_year_id:'',semester_id:'',release_at:'',grade_sheet_ids:[]})
const blankPeriod=()=>({academic_year_id:'',semester_id:'',midterm_opens_at:'',midterm_deadline:'',finals_opens_at:'',finals_deadline:'',status:'active'})
const periodForm=ref(blankPeriod()),editingPeriod=ref(null),editingAssessment=ref(null),assessmentForm=ref({label:'',category:'Quiz',max_score:100,display_order:1}),scoreDrafts=ref({})
const assessments=computed(()=>workspace.value?.sheet.assessments.filter(a=>a.period===activePeriod.value)||[])
const weights=computed(()=>workspace.value?.sheet.weights.filter(w=>w.period===activePeriod.value)||[])
const periodState=computed(()=>workspace.value?.schedule?.[`${activePeriod.value}_state`]||{state:'Unavailable',editable:false})
const editable=computed(()=>['draft','returned'].includes(workspace.value?.sheet?.status)&&(workspace.value?.sheet?.status==='returned'||periodState.value.editable))
const roster=computed(()=>{const q=search.value.toLowerCase();return(workspace.value?.roster||[]).filter(s=>!q||`${s.student_number} ${s.first_name} ${s.middle_name||''} ${s.last_name}`.toLowerCase().includes(q))})
const localDate=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):''
const fmt=v=>v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'Not configured'
const key=(s,a)=>`${s.enrollment_subject_id}:${a.id}`, oldScore=(s,a)=>a.scores?.find(x=>x.enrollment_subject_id===s.enrollment_subject_id)
const score=(s,a)=>scoreDrafts.value[key(s,a)]??oldScore(s,a)?.score??''
const raw=s=>assessments.value.reduce((n,a)=>n+(Number(score(s,a))||0),0)
async function load(){loading.value=true;error.value='';try{if(student.value)return;if(professor.value){const page=await gradingService.classes();classes.value=page.data||[]}else{const data=await gradingService.periods();periods.value=data.periods.data||[];options.value=data;reviewData.value=await gradingService.reviews();releaseData.value=await gradingService.releases()}}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
async function openClass(item){loading.value=true;error.value='';try{workspace.value=await gradingService.workspace(item.id);readiness.value=await gradingService.readiness(workspace.value.sheet.id);scoreDrafts.value={}}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
function editPeriod(item=null){editingPeriod.value=item;periodForm.value=item?{...item,midterm_opens_at:localDate(item.midterm_opens_at),midterm_deadline:localDate(item.midterm_deadline),finals_opens_at:localDate(item.finals_opens_at),finals_deadline:localDate(item.finals_deadline)}:blankPeriod();modal.value='period'}
async function savePeriod(){saving.value=true;error.value='';try{const p={...periodForm.value};if(editingPeriod.value)p.version=editingPeriod.value.version;editingPeriod.value?await gradingService.updatePeriod(editingPeriod.value.id,p):await gradingService.createPeriod(p);modal.value='';notice.value='Grade period saved.';await load()}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function archive(item){saving.value=true;try{await gradingService.archivePeriod(item.id,item.version);notice.value='Grade period archived.';await load()}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
function openAssessment(item=null){editingAssessment.value=item;assessmentForm.value=item?{label:item.label,category:item.category,max_score:item.max_score,display_order:item.display_order,version:item.version}:{label:'',category:'Quiz',max_score:100,display_order:assessments.value.length+1};modal.value='assessment'}
async function addAssessment(){saving.value=true;error.value='';try{const payload={...assessmentForm.value,period:activePeriod.value};editingAssessment.value?await gradingService.updateAssessment(workspace.value.sheet.id,editingAssessment.value.id,payload):await gradingService.addAssessment(workspace.value.sheet.id,payload);modal.value='';notice.value=editingAssessment.value?'Assessment updated.':'Assessment added.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function toggle(a){saving.value=true;try{await gradingService.assessmentStatus(workspace.value.sheet.id,a.id,{version:a.version,status:a.status==='active'?'archived':'active'});await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveWeights(){saving.value=true;error.value='';try{await gradingService.saveWeights(workspace.value.sheet.id,activePeriod.value,weights.value.map(w=>({category:w.category,weight_percentage:Number(w.weight_percentage),version:w.version})));notice.value='Category weights saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveScores(a){const scores=workspace.value.roster.map(s=>{const v=scoreDrafts.value[key(s,a)],old=oldScore(s,a);return v===undefined?null:{enrollment_subject_id:s.enrollment_subject_id,score:Number(v),...(old?{version:old.version}:{})}}).filter(Boolean);if(!scores.length){error.value='Enter at least one changed score.';return}saving.value=true;try{await gradingService.saveScores(workspace.value.sheet.id,{assessment_id:a.id,scores});notice.value='Draft scores saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveFinalWeights(){saving.value=true;try{await gradingService.saveFinalWeights(workspace.value.sheet.id,{midterm_weight:Number(workspace.value.sheet.midterm_weight),finals_weight:Number(workspace.value.sheet.finals_weight),version:workspace.value.sheet.version});notice.value='Final weighting saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function submitSheet(){saving.value=true;error.value='';try{await gradingService.submit(workspace.value.sheet.id,workspace.value.sheet.version);notice.value=workspace.value.sheet.status==='returned'?'Grade sheet resubmitted.':'Grade sheet submitted to Registrar.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function openReview(item){loading.value=true;try{reviewSheet.value=await gradingService.review(item.id);returnReason.value='';modal.value='review'}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
async function loadReviews(){loading.value=true;error.value='';try{reviewData.value=await gradingService.reviews(reviewFilters.value)}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
async function reviewAction(action){saving.value=true;error.value='';try{await runWithStepUp(()=>action==='approve'?gradingService.approve(reviewSheet.value.id,reviewSheet.value.version):gradingService.returnSheet(reviewSheet.value.id,reviewSheet.value.version,returnReason.value));modal.value='';notice.value=action==='approve'?'Grade sheet approved.':'Grade sheet returned to Professor.';await load()}catch(e){if(!isStepUpCancelled(e))error.value=gradingError(e)}finally{saving.value=false}}
async function createRelease(){saving.value=true;error.value='';try{await gradingService.createRelease({...releaseForm.value,grade_sheet_ids:releaseForm.value.grade_sheet_ids.map(Number)});notice.value='Grade release scheduled.';releaseForm.value={academic_year_id:'',semester_id:'',release_at:'',grade_sheet_ids:[]};await load()}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function releaseNow(item){saving.value=true;try{await runWithStepUp(()=>gradingService.executeRelease(item.id));notice.value='Approved grades published.';await load()}catch(e){if(!isStepUpCancelled(e))error.value=gradingError(e)}finally{saving.value=false}}
async function exportClass(){if(!reviewSheet.value)return;saving.value=true;error.value='';try{const response=await gradingService.classExport(reviewSheet.value.id);const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download=response.headers['content-disposition']?.match(/filename="?([^";]+)"?/)?.[1]||'class-grade-sheet.csv';a.click();URL.revokeObjectURL(url)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
onMounted(load)
</script>

<template><StudentGradesView v-if="student"/><main v-else class="grading-page">
<header class="grading-hero"><div><p class="grading-eyebrow">Academic records</p><h1>{{professor?'Grading · My Classes':'Grading Management'}}</h1><p>{{professor?'Compute and submit grades from your official assigned classes.':'Configure periods, review submissions, and control grade publication.'}}</p></div><button v-if="!professor&&staffTab==='periods'" class="grading-button primary" @click="editPeriod()">Create Grade Period</button></header>
<p v-if="notice" class="grading-alert success">{{notice}}</p><p v-if="error" class="grading-alert error" role="alert">{{error}}</p><div v-if="loading" class="grading-state">Loading grading workspace…</div>
<nav v-if="!professor&&!loading" class="grading-tabs" aria-label="Grading management"><button :class="{active:staffTab==='periods'}" @click="staffTab='periods'">Grade Periods</button><button :class="{active:staffTab==='reviews'}" @click="staffTab='reviews'">Grade Approval</button><button :class="{active:staffTab==='releases'}" @click="staffTab='releases'">Release &amp; Schedule</button></nav>
<template v-else-if="professor"><nav v-if="!workspace" class="grading-tabs" aria-label="Professor grading"><button :class="{active:professorTab==='classes'}" @click="professorTab='classes'">My Classes</button><button :class="{active:professorTab==='messages'}" @click="professorTab='messages'">Grade Messages</button></nav><ProfessorGradeMessages v-if="!workspace&&professorTab==='messages'"/><template v-else-if="!workspace"><section class="grading-toolbar"><label><span>Search classes</span><input v-model="search" type="search" placeholder="Subject or section"></label></section><div v-if="!classes.length" class="grading-state"><strong>No assigned classes</strong><span>Classes appear after Scheduling assigns an active Professor.</span></div><section v-else class="grading-class-grid"><button v-for="item in classes.filter(x=>!search||`${x.subject_code} ${x.subject_name} ${x.section}`.toLowerCase().includes(search.toLowerCase()))" :key="item.id" class="grading-class-card" @click="openClass(item)"><span>{{item.program}} · Year {{item.year_level}}</span><strong>{{item.subject_code}} — {{item.subject_name}}</strong><span>{{item.section}} · {{item.semester}}</span><span>{{item.units}} Units · {{item.student_count}} Students</span><div><em :data-state="item.schedule?.midterm_state?.state">Midterm: {{item.schedule?.midterm_state?.state||'Unavailable'}}</em><em :data-state="item.schedule?.finals_state?.state">Finals: {{item.schedule?.finals_state?.state||'Unavailable'}}</em></div></button></section></template>
<template v-else><button class="grading-back" @click="workspace=null;load()">← Back to My Classes</button><section class="grading-summary"><div><small>Subject</small><strong>{{workspace.class.subject_code}} — {{workspace.class.subject_name}}</strong></div><div><small>Section</small><strong>{{workspace.class.section}}</strong></div><div><small>Academic term</small><strong>{{workspace.class.academic_year}} · {{workspace.class.semester}}</strong></div><div><small>Roster</small><strong>{{workspace.roster.length}} Students</strong></div><div><small>Status</small><strong class="grading-status">{{workspace.sheet.status}}</strong></div></section><p v-if="workspace.sheet.status==='returned'" class="grading-alert error"><strong>Returned:</strong> {{workspace.sheet.return_reason}}</p><section class="grading-readiness"><div><strong>Submission readiness</strong><span>{{readiness?.ready?'Complete and ready for submission':`${readiness?.errors?.length||0} issue(s) must be resolved`}}</span><ul v-if="readiness?.errors?.length"><li v-for="item in readiness.errors" :key="item">{{item}}</li></ul></div><div class="grading-final-weights"><label>Midterm %<input v-model.number="workspace.sheet.midterm_weight" type="number" min="0" max="100" :disabled="!editable"></label><label>Finals %<input v-model.number="workspace.sheet.finals_weight" type="number" min="0" max="100" :disabled="!editable"></label><button :disabled="saving||!editable" @click="saveFinalWeights">Save final weights</button><button class="grading-button primary" :disabled="saving||!readiness?.ready||!['draft','returned'].includes(workspace.sheet.status)" @click="submitSheet">{{workspace.sheet.status==='returned'?'Resubmit to Registrar':'Submit to Registrar'}}</button></div></section><nav class="grading-tabs"><button v-for="p in ['midterm','finals']" :key="p" :class="{active:activePeriod===p}" @click="activePeriod=p">{{p}}</button><button type="button" :class="{active:activePeriod==='final'}" @click="activePeriod='final'">Final Grade</button></nav><template v-if="activePeriod!=='final'"><section class="grading-window" :data-state="periodState.state"><strong>{{activePeriod}}: {{periodState.state}}</strong><span>{{periodState.state==='Upcoming'?'Opens':'Deadline'}} {{fmt(periodState.state==='Upcoming'?periodState.opens_at:periodState.deadline)}}</span></section><section class="grading-weights"><label v-for="w in weights" :key="w.id"><span>{{w.category}} %</span><input v-model.number="w.weight_percentage" type="number" min="0" max="100" step=".01" :disabled="!editable"></label><button :disabled="saving||!editable" @click="saveWeights">Save weights</button></section><section class="grading-toolbar"><label><span>Search Student</span><input v-model="search" type="search" placeholder="Student number or name"></label><button class="grading-button primary" :disabled="!editable" @click="openAssessment()">Add Assessment</button></section>
<div v-if="!workspace.roster.length" class="grading-state"><strong>No enrolled Students</strong><span>The roster uses finalized Enrollment and enrolled-subject records.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th class="sticky number">#</th><th class="sticky identity">Student</th><th v-for="a in assessments" :key="a.id"><span>{{a.label}}</span><small>{{a.category}} · /{{a.max_score}}</small><button :disabled="!editable" @click="openAssessment(a)">Edit</button><button :disabled="!editable" @click="toggle(a)">{{a.status==='active'?'Remove':'Restore'}}</button></th><th>Raw total</th></tr></thead><tbody><tr v-for="(s,i) in roster" :key="s.enrollment_subject_id"><td class="sticky number">{{i+1}}</td><td class="sticky identity"><strong>{{s.last_name}}, {{s.first_name}}</strong><small>{{s.student_number}}</small></td><td v-for="a in assessments" :key="a.id"><input v-if="a.status==='active'" type="number" min="0" :max="a.max_score" step=".01" :disabled="!editable" :value="score(s,a)" @input="scoreDrafts[key(s,a)]=$event.target.value"><span v-else>Archived</span></td><td>{{raw(s)}}</td></tr></tbody><tfoot><tr><td :colspan="2+assessments.length"></td><td><div class="grading-save-list"><button v-for="a in assessments.filter(x=>x.status==='active')" :key="a.id" :disabled="saving||!editable" @click="saveScores(a)">Save {{a.label}}</button></div></td></tr></tfoot></table></div></template><div v-else class="grading-table-wrap"><table><thead><tr><th>Student Number</th><th>Student Name</th><th>Midterm</th><th>Finals</th><th>Final Grade</th><th>Grade Point</th><th>Remarks</th></tr></thead><tbody><tr v-for="result in readiness?.results||[]" :key="result.enrollment_subject_id"><td>{{result.student_number}}</td><td>{{result.student_name}}</td><td>{{result.midterm_grade}}</td><td>{{result.finals_grade}}</td><td><strong>{{result.final_grade}}</strong></td><td>{{result.grade_point??'Not configured'}}</td><td>{{result.remarks??'Not configured'}}</td></tr></tbody></table></div></template></template>
<template v-else-if="staffTab==='periods'"><div v-if="!periods.length" class="grading-state"><strong>No grade periods configured</strong><span>Create the first term schedule to open score entry.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th>Academic term</th><th>Midterm</th><th>Finals</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in periods" :key="item.id"><td><strong>{{item.academic_year.school_year}}</strong><small>{{item.semester.semester_name}}</small></td><td><em :data-state="item.midterm_state.state">{{item.midterm_state.state}}</em><small>{{fmt(item.midterm_opens_at)}} – {{fmt(item.midterm_deadline)}}</small></td><td><em :data-state="item.finals_state.state">{{item.finals_state.state}}</em><small>{{fmt(item.finals_opens_at)}} – {{fmt(item.finals_deadline)}}</small></td><td>{{item.status}}</td><td><button @click="editPeriod(item)">Edit</button><button v-if="item.status==='active'" @click="archive(item)">Archive</button></td></tr></tbody></table></div></template>
<template v-else-if="staffTab==='reviews'"><section class="grading-summary"><div><small>Pending Review</small><strong>{{reviewData.summary.pending_review}}</strong></div><div><small>Approved</small><strong>{{reviewData.summary.approved}}</strong></div><div><small>Published</small><strong>{{reviewData.summary.published}}</strong></div></section><form class="grading-review-filters" @submit.prevent="loadReviews"><label>Search<input v-model="reviewFilters.search" type="search" placeholder="Professor, subject, or section"></label><label>Academic Year<select v-model="reviewFilters.academic_year_id"><option value="">All</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select></label><label>Semester<select v-model="reviewFilters.semester_id"><option value="">All</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select></label><label>Program<select v-model="reviewFilters.course_id"><option value="">All</option><option v-for="c in options.courses" :key="c.id" :value="c.id">{{c.course_code}}</option></select></label><label>Year Level<select v-model="reviewFilters.year_level"><option value="">All</option><option v-for="y in [1,2,3,4]" :key="y" :value="y">Year {{y}}</option></select></label><label>Section<select v-model="reviewFilters.section_id"><option value="">All</option><option v-for="s in options.sections" :key="s.id" :value="s.id">{{s.section_name}}</option></select></label><label>Subject<select v-model="reviewFilters.subject_id"><option value="">All</option><option v-for="s in options.subjects" :key="s.id" :value="s.id">{{s.subject_code}}</option></select></label><label>Professor<select v-model="reviewFilters.professor_id"><option value="">All</option><option v-for="p in options.professors" :key="p.id" :value="p.id">{{p.user.profile.first_name}} {{p.user.profile.last_name}}</option></select></label><label>Status<select v-model="reviewFilters.status"><option value="">All</option><option value="submitted">Submitted</option><option value="approved">Approved</option><option value="published">Published</option></select></label><button class="grading-button primary">Apply Filters</button></form><div v-if="!reviewData.sheets.data.length" class="grading-state"><strong>No grade sheets found</strong><span>Submitted sheets appear here for formal review.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th>Date Submitted</th><th>Professor</th><th>Subject</th><th>Section</th><th>Students</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="item in reviewData.sheets.data" :key="item.id"><td>{{fmt(item.submitted_at)}}</td><td>{{item.professor.user.profile.first_name}} {{item.professor.user.profile.last_name}}</td><td>{{item.section_subject.subject.subject_code}} — {{item.section_subject.subject.subject_name}}</td><td>{{item.section_subject.section.section_name}}</td><td>{{item.latest_submission?.students_count||0}}</td><td><em :data-state="item.status">{{item.status}}</em></td><td><button @click="openReview(item)">Review</button></td></tr></tbody></table></div></template>
<template v-else><form class="grading-release-form" @submit.prevent="createRelease"><h2>Schedule approved grades</h2><label>Academic Year<select v-model="releaseForm.academic_year_id" required><option disabled value="">Select</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select></label><label>Semester<select v-model="releaseForm.semester_id" required><option disabled value="">Select</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select></label><label>Release date and time<input v-model="releaseForm.release_at" type="datetime-local" required></label><fieldset><legend>Approved grade sheets</legend><label v-for="sheet in releaseData.approved_sheets" :key="sheet.id"><input v-model="releaseForm.grade_sheet_ids" type="checkbox" :value="sheet.id"> {{sheet.section_subject.subject.subject_code}} · {{sheet.section_subject.section.section_name}}</label><p v-if="!releaseData.approved_sheets.length">No approved grade sheets are waiting for release.</p></fieldset><button class="grading-button primary" :disabled="saving||!releaseForm.grade_sheet_ids.length">Create Release Schedule</button></form><div v-if="!releaseData.schedules.data.length" class="grading-state"><strong>No release schedules</strong><span>Approved sheets remain private until scheduled and released.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th>Term</th><th>Release time</th><th>Grade sheets</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="item in releaseData.schedules.data" :key="item.id"><td>{{item.academic_year.school_year}} · {{item.semester.semester_name}}</td><td>{{fmt(item.release_at)}}</td><td>{{item.items.length}}</td><td><em :data-state="item.status">{{item.status}}</em></td><td><button v-if="item.status==='scheduled'" :disabled="saving" @click="releaseNow(item)">Release Now</button></td></tr></tbody></table></div></template>
<div v-if="modal" class="grading-modal-backdrop" @click.self="modal=''"> <section class="grading-modal" role="dialog" aria-modal="true"><header><h2>{{modal==='period'?(editingPeriod?'Edit Grade Period':'Create Grade Period'):modal==='review'?'Review Grade Sheet':(editingAssessment?'Edit Assessment':'Add Assessment')}}</h2><button aria-label="Close" @click="modal=''">×</button></header><form v-if="modal==='period'" @submit.prevent="savePeriod"><label><span>School Year</span><select v-model="periodForm.academic_year_id" required><option disabled value="">Select</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select></label><label><span>Semester</span><select v-model="periodForm.semester_id" required><option disabled value="">Select</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select></label><label><span>Midterm opens</span><input v-model="periodForm.midterm_opens_at" type="datetime-local" required></label><label><span>Midterm deadline</span><input v-model="periodForm.midterm_deadline" type="datetime-local" required></label><label><span>Finals opens</span><input v-model="periodForm.finals_opens_at" type="datetime-local" required></label><label><span>Finals deadline</span><input v-model="periodForm.finals_deadline" type="datetime-local" required></label><footer><button type="button" @click="modal=''">Cancel</button><button class="grading-button primary" :disabled="saving">Save Period</button></footer></form><form v-else-if="modal==='assessment'" @submit.prevent="addAssessment"><label><span>Label</span><input v-model.trim="assessmentForm.label" required maxlength="80"></label><label><span>Category</span><select v-model="assessmentForm.category"><option v-for="c in workspace.categories" :key="c">{{c}}</option></select></label><label><span>Maximum score</span><input v-model.number="assessmentForm.max_score" type="number" min=".01" step=".01" required></label><label><span>Order</span><input v-model.number="assessmentForm.display_order" type="number" min="1" required></label><footer><button type="button" @click="modal=''">Cancel</button><button class="grading-button primary" :disabled="saving">Add Assessment</button></footer></form><div v-else-if="reviewSheet" class="grading-review-detail"><section class="grading-summary"><div><small>Subject</small><strong>{{reviewSheet.section_subject.subject.subject_code}} — {{reviewSheet.section_subject.subject.subject_name}}</strong></div><div><small>Section</small><strong>{{reviewSheet.section_subject.section.section_name}}</strong></div><div><small>Professor</small><strong>{{reviewSheet.professor.user.profile.first_name}} {{reviewSheet.professor.user.profile.last_name}}</strong></div><div><small>Term</small><strong>{{reviewSheet.section_subject.section.academic_year.school_year}} · {{reviewSheet.section_subject.section.semester.semester_name}}</strong></div><div><small>Submitted</small><strong>{{fmt(reviewSheet.submitted_at)}}</strong></div><div><small>Status</small><strong>{{reviewSheet.status}}</strong></div></section><div class="grading-table-wrap"><table><thead><tr><th>Student Number</th><th>Student Name</th><th>Midterm</th><th>Finals</th><th>Final Grade</th><th>Grade Point</th><th>Remarks</th></tr></thead><tbody><tr v-for="student in reviewSheet.latest_submission.students" :key="student.id"><td>{{student.student_number}}</td><td>{{student.student_name}}</td><td>{{student.midterm_grade}}</td><td>{{student.finals_grade}}</td><td><strong>{{student.final_grade}}</strong></td><td>{{student.grade_point??'Not configured'}}</td><td>{{student.remarks??'Not configured'}}</td></tr></tbody></table></div><label v-if="reviewSheet.status==='submitted'">Return reason<textarea v-model.trim="returnReason" rows="3" maxlength="2000" placeholder="Explain what the Professor must correct"></textarea></label><footer><button v-if="['approved','published'].includes(reviewSheet.status)" type="button" :disabled="saving" @click="exportClass">Export CSV</button><template v-if="reviewSheet.status==='submitted'"><button type="button" :disabled="saving||returnReason.length<3" @click="reviewAction('return')">Reject &amp; Return</button><button type="button" class="grading-button primary" :disabled="saving" @click="reviewAction('approve')">Approve</button></template></footer></div></section></div>
</main></template>
